<section class="auth-card"><p class="eyebrow"><?= $admin ? 'Restricted area' : 'Welcome back' ?></p><h1><?= e($title) ?></h1><form method="post" action="<?= $admin ? '/sa/login' : '/login' ?>" class="form-stack"><?= csrf_field() ?><label>Email<input type="email" name="email" value="<?= e(old('email')) ?>" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="button primary" type="submit">Sign in</button></form><?php if (!$admin): ?><div class="auth-links"><a href="/password/forgot">Forgot password?</a><a href="/register">Create an account</a></div><?php endif ?></section>
